import{_ as o,l as r,o as e,c as l,v as t,p as s,x as i,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"最小表示法","description":"","frontmatter":{"title":"最小表示法","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/minimal-rotation.md","filePath":"cs/minimal-rotation.md","lastUpdated":1789023840000}'),c={name:"cs/minimal-rotation.md"};function m(_,a,u,B,f,k){const n=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="最小表示法" tabindex="-1">最小表示法 <a class="header-anchor" href="#最小表示法" aria-label="Permalink to &quot;最小表示法&quot;">​</a></h1><div class="epigraph"><p>循环串的最小表示是所有旋转里字典序最小者；双指针在 $O(n)$ 内丢掉不可能更小的起点。</p><footer>—— 据 Booth, Lexicographically Least Circular Strings, 1980；Duval 与 Lyndon 对照后课整理</footer></div><p>上一课<a href="/cs/manacher">Manacher</a>处理回文。循环同构：项链、循环码。缺口是最小表示：起点 \\(i\\) 使 \\(s[i..]+s[0..i)\\) 最小。不重写回文半径。后课后缀数组应用、再后 Lyndon。本课双指针即可。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>朴素比较所有旋转 \\(O(n^2)\\)。算法：指针 \\(i,j\\) 为候选起点，\\(k\\) 为已比长度。\\(s[i+k]\\lt s[j+k]\\) 则 \\(j\\) 跳过一段，\\(j\\leftarrow j+k+1\\)；反之 \\(i\\) 跳。保证 \\(i\\neq j\\)，均摊 \\(O(n)\\)。结果 \\(\\min(i,j)\\)（还要处理越界取模）。</p><p>缺口是循环字典序，不是 Z 的线性 LCP（虽可用 \\(s+s\\) 的后缀最小，后缀数组后课）。</p><h3 id="不是排序全体旋转" tabindex="-1">不是排序全体旋转 <a class="header-anchor" href="#不是排序全体旋转" aria-label="Permalink to &quot;不是排序全体旋转&quot;">​</a></h3><p>不必生成 \\(n\\) 个串。最小表示唯一（若要唯一再规定规则）。不要 \\(n\\) 次 KMP。</p><p><span class="marginnote">Booth 1980。Lyndon 分解给出另一构造（后课 Duval）。后课 SA 可 \\(O(n)\\) 或 \\(O(n\\log n)\\) 找最小后缀于 \\(s+s\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>\\(i=0,j=1\\)。循环直到候选扫过 \\(n\\)。注意 \\(i+k\\) 取模。输出从起点切断。</p>',11)),(e(),s(p,null,{default:i(()=>[h(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20IJ%5B%22%E5%80%99%E9%80%89%E8%B5%B7%E7%82%B9%20i%2C%20j%22%5D%20--%3E%20K%5B%22%E6%AF%94%20s%5Bi%2Bk%5D%20%E4%B8%8E%20s%5Bj%2Bk%5D%22%5D%0A%20%20K%20--%3E%20SKIP%5B%22%E5%8A%A3%E8%80%85%E8%B7%B3%20k%2B1%22%5D%0A%20%20SKIP%20--%3E%20MIN%5B%22%E6%9C%80%E5%B0%8F%E8%B5%B7%E7%82%B9%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>有相等环要防死循环，标准实现会把指针推过 \\(n\\)。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>更小字符出现时，对方起点及其后 \\(k\\) 个位置都不可能最优。类似 KMP 的失配跳跃，对象是两个旋转。与 Lyndon：最小表示与 Lyndon 共轭相关，后课再收。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写带权旋转。不写二维循环。后课默认：循环最小表示线性双指针。下一课后缀数组的应用。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>循环字典序最小旋转，\\(O(n)\\) 双指针。</li><li>不必枚举全部旋转。</li><li>与 Lyndon/SA 后课接口。</li><li>出处：Booth, 1980。</li></ul>',7))])}const b=o(c,[["render",m]]);export{P as __pageData,b as default};
